 qsa('[data-ti-tab]').forEach(b=>b.addEventListener('click',()=>{state.activeTab=b.dataset.tiTab;state.lastStep=state.activeTab==='context'?'disease':state.activeTab==='drug'?'dose':state.activeTab==='sources'?'verify':'groups';renderTabs();statusMsg(`Opened ${b.textContent.trim()}.`)}));
